import org.apache.flink.streaming.api.functions.source.SourceFunction;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;

/**
 * Source functions that read gzipped CSV files of cluster-usage trace events.
 *
 * The files are expected to already be sorted by timestamp (they are in the
 * Google trace), so downstream operators can rely on nearly-in-order event
 * time with a small bounded out-of-orderness watermark.
 */
public class GzipCsvSources {

    public static class TaskSource implements SourceFunction<TaskEvent> {
        private final String path;
        private volatile boolean running = true;

        public TaskSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            try (InputStream fis = new FileInputStream(path);
                 InputStream gis = new GZIPInputStream(fis);
                 BufferedReader br = new BufferedReader(new InputStreamReader(gis, StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = br.readLine()) != null) {
                    TaskEvent e = TaskEvent.parse(line);
                    if (e != null) {
                        ctx.collect(e);
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }

    public static class JobSource implements SourceFunction<JobEvent> {
        private final String path;
        private volatile boolean running = true;

        public JobSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<JobEvent> ctx) throws Exception {
            try (InputStream fis = new FileInputStream(path);
                 InputStream gis = new GZIPInputStream(fis);
                 BufferedReader br = new BufferedReader(new InputStreamReader(gis, StandardCharsets.UTF_8))) {
                String line;
                while (running && (line = br.readLine()) != null) {
                    JobEvent e = JobEvent.parse(line);
                    if (e != null) {
                        ctx.collect(e);
                    }
                }
            }
        }

        @Override
        public void cancel() {
            running = false;
        }
    }
}
