file_editor: {"command": "create", "path": "/app/workspace/src/main/java/clusterdata/utils/FileLineSink.java", "file_text": "package clusterdata.utils;

import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;

import java.io.BufferedWriter;
import java.io.File;
import java.io.FileWriter;

/**
 * Simple sink that writes each incoming string as a line to a local file.
 * Designed for parallelism=1 use.
 */
public class FileLineSink extends RichSinkFunction<String> {

    private final String path;
    private transient BufferedWriter writer;

    public FileLineSink(String path) {
        this.path = path;
    }

    @Override
    public void open(Configuration parameters) throws Exception {
        File f = new File(path);
        File parent = f.getParentFile();
        if (parent != null && !parent.exists()) {
            parent.mkdirs();
        }
        writer = new BufferedWriter(new FileWriter(f, false));
    }

    @Override
    public void invoke(String value, Context context) throws Exception {
        writer.write(value);
        writer.newLine();
    }

    @Override
    public void close() throws Exception {
        if (writer != null) {
            writer.flush();
            writer.close();
        }
    }
}
