                .addSource(jobSourceOrTest(new GzipCsvSources.JobSource(jobInput)))
                .returns(JobEvent.class)
                .name("job-events");

        // --- Session windows over SUBMIT task events -----------------------
        // Only SUBMIT events (event type 0) demarcate stages.
        DataStream<TaskEvent> submits = taskEvents
                .filter(e -> e.getEventType() == TaskEvent.SUBMIT)
                .assignTimestampsAndWatermarks(
